  "anomalies": [
    {
      "category": "bridged_nets",
      "components": ["FCC1"],
      "pins": ["FCC1.48", "FCC1.73"],
      "nets": ["UART3_TX_FCC", "GND"],
      "observed": "FCC1 pin 48, marked VCAP, is connected to UART3_TX_FCC. FCC1 pin 73, also marked VCAP, is left unconnected; neither pin has the required core-regulator capacitor connection.",
      "expected": "The STM32H753 VCAP pins should be decoupled as required by the MCU datasheet, not used as a UART signal or left open.",
      "evidence": [
        {
          "source": "schematic",
          "quote": "48 VCAP UART3_TX_FCC; 73 VCAP [no-connect marker] (FCC sheet, page 2)"
        },
        {
          "source": "spec",
          "quote": "Flight Control Computer MCU: FCC1 | STM32H753VITx (Cortex-M7, LQFP-100) (§2)"
        }
      ],
      "impact": "The core-regulator supply may fail to stabilize, preventing reliable MCU operation; the UART3_TX_FCC net is also not driven by the intended MCU UART pin.",
      "confidence": 0.98
    },
    {
      "category": "extra_component",
      "components": ["U11 (74LVC1G34, FCC sheet)"],
      "pins": ["U11.2", "U11.4"],
      "nets": ["Troj_UART_IN", "UART3_RX"],
      "observed": "An unlisted 74LVC1G34 buffer has its input labeled Troj_UART_IN and its output labeled UART3_RX.",
      "expected": "The schematic should not contain an unexplained signal-injection buffer; the design specification describes no Troj_UART_IN interface or such a buffer.",
      "evidence": [
        {
          "source": "schematic",
          "quote": "74LVC1G34; Troj_UART_IN; UART3_RX (FCC sheet, page 2)"
        },
        {
          "source": "spec",
          "quote": "USB-UART bridges (programming/debug) | otter_CH330 ×2 (§2)"
        }
      ],
      "impact": "If Troj_UART_IN is driven, the added gate can inject a logic signal onto UART3_RX, potentially altering serial communication.",
      "confidence": 0.9
    }
  ],
  "summary": "The FCC STM32H753 VCAP pins are incorrectly connected: one is assigned to UART3_TX_FCC and the other is left open instead of being properly decoupled. The FCC sheet also shows an unexplained buffer labeled Troj_UART_IN driving UART3_RX."
}

